          const metrics = [["API cost", "API-equivalent cost ($)"], ["Tokens", "Tokens"], ["Cache hit rate", "Cache hit"], ["Seats", "Seats with data"], ["Seat-time", "Active seat-hours"], ["Orchestrator time", "Orchestrator time"], ["Issues done", "Done"], ["In progress", "In progress"], ["To do", "Todo"]];
          const metric = ([label, key]: string[]) => { const delta = get(key === "Done" ? "Δ done" : key === "In progress" ? "Δ in progress" : key === "Todo" ? "Δ todo" : `Δ ${key}`), value = get(key!), deltaLabel = key === "Cache hit" ? "Cache hit (pp)" : key!, text = ["Done", "In progress", "Todo"].includes(key!) && get("Before Jira captured") !== 1 ? "not captured" : typeof delta === "number" ? reportComparedChange(delta, deltaLabel) : "not captured", base = Number(value) - Number(delta), relative = text !== "±0" && typeof delta === "number" && ["API-equivalent cost ($)", "Tokens", "Seats with data", "Active seat-hours", "Orchestrator time"].includes(key!) ? base > 0 ? ` (${delta >= 0 ? "+" : "−"}${(100 * Math.abs(delta) / base).toFixed(1)}%)` : " new" : ""; return <View key={key} style={{ minWidth: 64 }}><Text style={{ color: colors.foregroundMuted, fontSize: 11, lineHeight: 20, fontWeight: "600", letterSpacing: 0.33 }}>{label!.toUpperCase()}</Text><Text style={{ color: colors.foreground, fontSize: 15, lineHeight: 24, fontWeight: "600", fontVariant: ["tabular-nums"] }}>{reportValue(value, key)}</Text>{comparing ? <Text testID={`report-workstream-change-${key}`} style={{ color: text !== "±0" && typeof delta === "number" ? colors.accent : colors.foregroundMuted, fontWeight: text === "±0" ? "400" : "600", fontSize: 13, lineHeight: 20 }}>{text}<Text style={{ color: colors.foregroundMuted, fontWeight: "400", fontSize: 11 }}>{relative}</Text></Text> : null}</View>; };

